s","html_tag":"h3","headings_by_tags":["h3"],"exclude_headings_by_selector":[],"border_color":"#3A4347","header_background_color":"#3A4347","header_text_color":"#FFFFFF","header_typography_typography":"custom","header_typography_font_family":"Montserrat","header_typography_font_weight":"600","toggle_button_color":"#FFFFFF","list_typography_typography":"custom","list_typography_font_family":"Montserrat","list_typography_font_weight":"400","item_text_color_hover":"#3A4347","pa_condition_repeater":[{"_id":"5173123"}],"pa_cursor_ftext":"Premium Follow Text","pa_badge_text":"New","custom_css":".elementor-toc__list-item-text-wrapper:before{
