rn","pa_condition_post":[],"pa_condition_post_type":[],"pa_condition_page":[],"pa_condition_static_page":"home","pa_condition_operating_system":["windows"],"pa_condition_user_role":[],"pa_condition_timezone":"server"}],"pa_cursor_ftext":"Premium Follow Text","pa_badge_text":"New"},"elements":[{"id":"12588d0","elType":"widget","settings":{"share_buttons":[{"_id":"7a6ea4f"},{"button":"linkedin","_id":"709faff"},{"button":"twitter","_id":"c0a1579"},{"button":"email","_id":"f5e66bc"}],"view":"icon","skin":"flat","alignment":"right","column_gap":{"unit":"px","size":0,"sizes":[]},"row_gap":{"unit":"px","size":0,"sizes":[]},"button_size":{"unit":"px","size":2,"sizes":[]},"icon_size":{"unit":"em","size":4,"sizes":[]},"color_source":"custom","primary_color":"#ffffff","secondary_color":"#3A4347","secondary_color_hover":"#3A4347","alignment_mobile":"center","pa_condition_repeater":[{"_id":"e66a752","pa_condition_key":"browser","pa_condition_valshortcode":"","pa_condition_valtime_range":"","pa_condition_operator":"is","pa_condition_url_string":"","pa_condition_url_referer":"","pa_condition_shortcode":"","pa_condition_browser":"chrome","pa_condition_device":"desktop","pa_condition_day":["sunday"],"pa_condition_date":"2022/09/05","pa_condition_date_range":"2022/09/05","pa_condition_time_range":"","pa_condition_ip_location":[],"pa_condition_lang":[],"pa_condition_login_status":"logged","pa_condition_return_visitor":"return","pa_condition_post":[],"pa_condition_post_type":[],"pa_condition_page":[],"pa_condition_static_page":"home","pa_condition_operating_system":["windows"],"pa_condition_user_role":[],"pa_condition_timezone":"server"}],"pa_cursor_ftext":"Premium Follow Text","pa_badge_text":"New","button_height":{"unit":"em","size":1,"sizes":[]}},"elements":[],"widgetType":"share-buttons"}],"isInner":"1"}],"isInner":"1"},{"id":"3167c6c3","elType":"widget","settings":{"space":{"unit":"px","size":30,"sizes":[]}},"elements":[],"widgetType":"spacer"},{"id":"f5cfe25","elType":"widget","settings":{"editor":"<p>If you are looking for the smartest Ecommerce SEO tips, this is the ultimate guide. In this guide, I will show you everything that you need to know about the optimization of an Ecommerce site.</p><p>Right from comprehensive keyword research to the technical SEO link building, I’ve got you covered.</p><p>That’s just it – a complete guide to getting more traffic and high level conversions.</p><p>Let’s hit the road.</p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"4aa94b5","elType":"widget","settings":{"title":"Why is SEO Important for Ecommerce Websites?","wunderwp_presets":null,"title_color":"#3A4347","typography_typography":"custom","typography_font_weight":"600","typography_font_size":{"unit":"px","size":30,"sizes":[]},"_padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true}},"elements":[],"widgetType":"heading"},{"id":"4ffc890","elType":"widget","settings":{"editor":"<p>Before we get down to the juice, let me tell you why SEO is important for an Ecommerce Website.</p><p>It is stated that <a href="https://www.semrush.com/blog/how-leading-e-commerce-companies-drive-traffic-to-their-websites/">37.5% of the ecommerce traffic that online websites get</a> come from the search engines.</p><p>While <a href="https://www.businessinsider.com/most-online-shoppers-are-using-search-engines-before-they-buy-2016-4">23.6% of online conversions are tied to the traffic</a> that ecommerce websites normally generate.</p><p>If that’s the case, one thing is clear. SEO is vital in both the marketing and conversion rates of any ecommerce website. In short, SEO makes it easy to market and to sell and product or service. </p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"c91bab1","elType":"widget","settings":{"title":"Table of Contents","html_tag":"h3","headings_by_tags":["h3"],"exclude_headings_by_selector":[],"border_color":"#3A4347","header_background_color":"#3A4347","header_text_color":"#FFFFFF","header_typography_typography":"custom","header_typography_font_weight":"600","toggle_button_color":"#FFFFFF","list_typography_typography":"custom","list_typography_font_weight":"400","item_text_color_hover":"#3A4347","_margin":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"_padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"custom_css":".elementor-toc__list-item-text-wrapper:before{
    display: none !important;
}","no_headings_message":"No headings were found on this page."},"elements":[],"widgetType":"table-of-contents"},{"id":"64f7d14","elType":"widget","settings":{"space":{"unit":"px","size":30,"sizes":[]}},"elements":[],"widgetType":"spacer"},{"id":"9ab51aa","elType":"widget","settings":{"title":"Chapter I: Keyword Research for Ecommerce ","header_size":"h3","title_color":"#3A4347","typography_typography":"custom","typography_font_weight":"600","typography_font_size":{"unit":"px","size":30,"sizes":[]},"_padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true}},"elements":[],"widgetType":"heading"},{"id":"acd185f","elType":"widget","settings":{"editor":"<p>There is no doubt. Proper keyword research is the foundation of any SEO campaign including for the ecommerce websites.</p><p>If you are asking why, here is the simplest answer. Keyword research will influence any other SEO-based task that you intend to perform in your website.</p><p>Whether you are optimizing your product and category pages, creating a blog, or simply working on optimizing the images that you use on your ecommerce website, keyword research will be at the center of it.</p><p>As such, keyword research will influence everything that you are doing including the technical SEO strategy.</p><p>So how can you get the best keywords that your prospects use? Take a look at the next part of this chapter to get the best keywords for your ecommerce websites.</p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"bdda20c","elType":"widget","settings":{"title":"Finding Best Keywords for Ecommerce Category and Product Pages","header_size":"h4","title_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":23,"sizes":[]},"typography_font_weight":"600"},"elements":[],"widgetType":"heading"},{"id":"4d07dae","elType":"widget","settings":{"editor":"<p>If you look at the best keyword tutorials, you’ll realize that they focus more on working with informational keywords.</p><p>These are keywords that tend to inform the web visitor by answering their questions rather than addressing their concerns.</p><p>A good example of such a keyword is “how to feed fish.” While this type of keyword is important, in this post, I will focus more on keywords that are designed around product searches.</p><p>For instance, “<a href="https://ubid.com.ar/interior/lampara-de-techo/">Ceiling Lamps and Pendants</a>.” As such, my keyword research tutorial will focus more on a keyword research strategy that goes with product-focused keywords.</p><p>How can you do that? Take a look at the best options that you’ve got.</p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"838ab1c","elType":"widget","settings":{"title":"Amazon Suggest ","header_size":"h4","title_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":23,"sizes":[]},"typography_font_weight":"600"},"elements":[],"widgetType":"heading"},{"id":"8871e61","elType":"widget","settings":{"editor":"<p>Why Amazon suggest, while Amazon is my competitor?</p><p>Well, this is all true. However, Amazon is also the biggest ecommerce site. In this case, its product keyword is a treasure.</p><p>Here is what you can do to tap into the wealth of keywords that Amazon has.</p><ul><li>Head up to Amazon</li><li>Type in a keyword that best describes your products.</li><li>Amazon will list all the keyword suggestions.</li><li>Find the keywords suggestions that suits you.</li></ul><p>The keywords that you’ll get from Amazon are often very much targeted.</p><p>They are <strong><u>long tail keywords</u></strong> and will, therefore, convert better.</p><p>More importantly they are less competitive. If you are going with the most important products that you’ve got, you can repeat the process over and over again to get the best keywords.</p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"c08c2a5","elType":"widget","settings":{"title":"Use Keyword Tool Dominator ","header_size":"h4","title_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":23,"sizes":[]},"typography_font_weight":"600"},"elements":[],"widgetType":"heading"},{"id":"390bbd0","elType":"widget","settings":{"editor":"<p>For those who don’t know the <a href="http://www.keywordtooldominator.com/">Keyword Tool Dominator</a>, here is what it is. This is a cool <strong><u>keyword tool</u></strong> that helps you to scrape Amazon’s search suggestions.</p><p>It is simple to use and comes with a simple interface. Simple enter a seed keyword on its search box.</p><p>And it splits several keyword suggestions. You will see your results firsthand.</p><p><strong>NOTE:</strong></p><p>This tool is ideal if you are looking for the long tail keywords from the Amazon suggest. It works faster than typing the keyword directly.</p><p>In addition to that, you’ll also be left with a wider range of keywords to go with. One feature that makes the keyword tool dominator a great option is this. It offers you the chance to save your best keywords to a reference list.</p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"e009fb0","elType":"widget","settings":{"title":"Amazon and Competitor Categories","header_size":"h4","title_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":23,"sizes":[]},"typography_font_weight":"600"},"elements":[],"widgetType":"heading"},{"id":"fb88f8d","elType":"widget","settings":{"editor":"<p>From my experience working with several ecommerce businesses, I have realized that most ecommerce website owners will optimize their category pages to suit random keywords.</p><p>It not bad since they will have to think about what their competitors are doing too. However, it is not the real deal. Actually, it is a big mistake.</p><p>While the product categories may not work best for conversions like the product pages will, they will still generate some sales for you.</p><p>Remember, you need everything that you can to tap into any potential prospects. As such, it is worthwhile to tap into every potential keywords including those generated by the categories.</p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"98207b4","elType":"widget","settings":{"title":"What’s the best way to do that?","header_size":"h5","title_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"600","typography_text_decoration":"underline","typography_font_style":"italic"},"elements":[],"widgetType":"heading"},{"id":"fefd458","elType":"widget","settings":{"editor":"<p>Here are the best options.</p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"fc36de4","elType":"widget","settings":{"title":"Focus on Amazon and Competitor Categories ","header_size":"h4","title_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":23,"sizes":[]},"typography_font_weight":"600"},"elements":[],"widgetType":"heading"},{"id":"785bf39","elType":"widget","settings":{"editor":"<p>You should look at the categories that your competitors are already working with.</p><p>Let’s say that your competition is Amazon. What can you do? It is simple. Just hover over the “departments” tab that’s at the top of Amazon’s homepage.</p><p>If you do that, you’ll easily see the main categories that Amazon uses.</p><p>You will realize that there are a dozen more. You don’t have to focus on all of them. Instead, just click on any that is ideal for your needs.</p><p>Make sure that any “subcategory” that you choose suits your keywords.</p><p>Once you have found the subcategories, you can dig deeper to find the category-focused keywords.</p><p><strong>Example:</strong></p><p>Let’s say that you are focused on “Pet Supplies” Category.</p><p>Click on “Pet Supplies”</p><p>Then click on “Cats”</p><p>Choose “Toys” on the list</p><p>Then you will get on the sidebar a keyword that Amazon uses to describe their cat pet toys.</p><p>It is that simple!</p><p>It is true that Amazon will give you some of the best category-based keywords. However, it isn’t the only place that you can work with.</p><p>Instead, looking at the options that your niche-based competitors work with to describe their categories will be a great option too.</p><p>It will help you more. Go with niche-based products to ensure that you get the best out of every category that you choose.</p><p>Once you identify a competitor, you can always follow the same process that we did with Amazon above.</p><p>Then add the keywords that you’ve gotten to your list.</p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"1c0d365","elType":"widget","settings":{"title":"Wikipedia ","header_size":"h4","title_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":23,"sizes":[]},"typography_font_weight":"600"},"elements":[],"widgetType":"heading"},{"id":"a8cf9ba","elType":"widget","settings":{"editor":"<p>This might come as a surprise to most of you out there, well, it did to me.</p><p>However, it is the truth. Wikipedia is actually a great place to use when looking for the product and category page keywords.</p><p>The reason for this is simple. Like we saw above with Amazon and the Competitor websites, Wiki also organizes its content based on keywords and categories.</p><p>This means that if you are out to get a more targeted keywords, you’ll be better off with Wikipedia. So how can you use Wikipedia for ecommerce websites?</p><p>First enter the keyword that best describes your niche (in terms of category or product).</p><p>Then look through Wikipedia to find words and phrases that relate to the products that you sell.</p><p>Ensure that you take a keen look on the content’s box – you may find excellent product-based keywords.</p><p>List the keywords that you’ve come up with and save.</p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"66f7528","elType":"widget","settings":{"title":"SEMrush","header_size":"h4","title_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":23,"sizes":[]},"typography_font_weight":"600"},"elements":[],"widgetType":"heading"},{"id":"3964b85","elType":"widget","settings":{"editor":"<p>I know most of you are conversant with <a href="https://www.semrush.com/">SEMrush</a>. Even so, what I’ve already given you should be a great starting point.</p><p>But SEMrush comes with a twist. It does not generate your new keyword ideas from the seed keywords. Rather, it’ll show you the keywords that your competitors are already ranking for. Isn’t that great?</p><p>If you are looking at SEMrush as your best option, here is how to go about it.</p><p>Open SEMrush and identify the “search” tab</p><p>Next enter a competitor’s url on the search bar.</p><p>Then follow that by clicking “organic search” in the sidebar.</p><p>This action will show you every keyword that your competitor ranks for.</p><p>The deal is better if you want to tap into every keyword that your competitor uses.</p><p>Simply check on the competitor’s report which SEMrush generates for you.</p><p>More importantly, SEMrush will also show you every site that’s similar to the one you are looking at.</p><p>You can therefore repeat the same process by the competitor sites that you’ve just found on SEMrush.</p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"ddd09cf","elType":"widget","settings":{"title":"Google Keyword Planner","header_size":"h4","title_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":23,"sizes":[]},"typography_font_weight":"600"},"elements":[],"widgetType":"heading"},{"id":"b5b832f","elType":"widget","settings":{"editor":"<p>Finally, the one more tool that we have is the Google Keyword Planner.</p><p>This might not be very effective. However, it is not a bad way to start. But don’t expect so many unique keywords when using this tool.</p><p>Even so, it is a handy tool when it comes to finding <strong><u>search volume prospects</u></strong> and the <strong><u>commercial intent</u></strong>.</p><p>Next, let us find how to choose the right keywords for an ecommerce product and category page. </p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"e29f904","elType":"widget","settings":{"title":"Choosing the Ideal KWs for the Product and Category Page for Ecommerce ","header_size":"h4","title_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":23,"sizes":[]},"typography_font_weight":"600"},"elements":[],"widgetType":"heading"},{"id":"61417eb","elType":"widget","settings":{"editor":"<p>The tips that I gave you above only provide you with lists of potential keywords that you can use for your ecommerce products and categories.</p><p>However, they don’t guarantee the keyword that you should choose. So how do you choose the best keyword for your ecommerce product/category?</p><p>Here is a 4-step check list that’ll identify the very best keywords for your ecommerce websites.</p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"8efef22","elType":"widget","settings":{"title":"Step I: Search Volume","header_size":"h5","title_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"600","typography_font_style":"italic","typography_text_decoration":"underline"},"elements":[],"widgetType":"heading"},{"id":"be5ced6","elType":"widget","settings":{"editor":"<p>This is the most important thing when evaluating the best keyword for your use. In any case, if a keyword is not being sought then it doesn’t really matter.</p><p>Depending on your niche, find the right search volume for your keyword. You will find niches that 100 searches a month is huge and others that 10k searches monthly is nothing at all.</p><p>That’s why it is important that you understand the niche that you’re dealing with. This should show you what a “high volume” and “low volume” keyword will be for your industry.</p><p>To get the average monthly searches for the keyword that you are looking at, simply use the Google Keyword Planner (GKP).</p><p>It has an average monthly search column that you will use to identify the search volume for the keyword.</p><p>You can also see how keyword search fluctuates or changes throughout the year using the <a href="https://kwfinder.com/">KWFinder</a>. This tool shows you a clear chart with a month to month search volume for your KW.</p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"36ef229","elType":"widget","settings":{"title":"Step II: Product Fit KW","header_size":"h5","title_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"600","typography_font_style":"italic","typography_text_decoration":"underline"},"elements":[],"widgetType":"heading"},{"id":"e21e26f","elType":"widget","settings":{"editor":"<p>You can find a keyword that enjoys tons of search volume. Well, that’s a god sign. But does it guarantee that the keyword is fit for your product? Not at all.</p><p>Is the keyword receives tons of searches but it’s somewhat a stretch with what your website sells, however little, chances are that the people who search for that keyword won’t convert at all.</p><p>So it is very important that you ensure that the keyword that you are working with actually fits both your site and product.</p><p>In some cases the much targeted keyword might be getting fewer searches than the other keywords.</p><p>Well, I recommend that you stick to this keyword rather than going for the long shot. It is better to be safe than sorry.</p><p>Now that you’ve got the perfect fit keyword, let’s see how much of commercial intent do they have.</p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"96860da","elType":"widget","settings":{"title":"Step III: Commercial Intent","header_size":"h5","title_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"600","typography_font_style":"italic","typography_text_decoration":"underline"},"elements":[],"widgetType":"heading"},{"id":"a7cf1a4","elType":"widget","settings":{"editor":"<p>Can the keywords trigger a conversion? Can they make a visitor to get out their credit card and buy?</p><p>Here is the thing. Before you get down to using this keyword, you can take a pause and re-think to find out if the people who are focused on this KW buy or simple check and walk away.</p><p>How can you do that?</p><p>It’s easy. Simply use the Google Keyword Planner and follow these:</p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"89d5cb5","elType":"widget","settings":{"title":"Keyword Competition ","header_size":"h4","title_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":23,"sizes":[]},"typography_font_weight":"600"},"elements":[],"widgetType":"heading"},{"id":"03bd6ea","elType":"widget","settings":{"editor":"<p>To determine this you’ll have to start by checking out the “competition rating” of the keyword that you’ve chosen.</p><p>Competition: This column reflects on the number of people who are bidding on the keyword in Google Ads. If you get a high number of bidders, it means the keyword is a cash cow.</p><p>That’s why when working for ecommerce websites, going with “medium” and “high” competition KWs is the best thing to do.</p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"8f16fa5","elType":"widget","settings":{"title":"Top of Page Bid","header_size":"h4","title_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":23,"sizes":[]},"typography_font_weight":"600"},"elements":[],"widgetType":"heading"},{"id":"f99b50d","elType":"widget","settings":{"editor":"<p>You should also take a look at the “Top of Page Bid.” Top of Page Bid reflects on how much people spend on a single click on the Google Ads.</p><p>The higher the bid the better especially if you are trying to gauge the commercial intent.</p><p>Now that you’ve your suggested bid, you should also identify the phrases that often impact the estimated bid.</p><p>NOTE: The keywords with higher bids are also very competitive to rank for the Google Search. I will show you more about that soon.</p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"9d6b2ae","elType":"widget","settings":{"title":"Step IV: Ranking Competition ","header_size":"h5","title_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"600","typography_font_style":"italic","typography_text_decoration":"underline"},"elements":[],"widgetType":"heading"},{"id":"2ea86e9","elType":"widget","settings":{"editor":"<p>Finally, you have to see how hard or easy it is for the keyword to crack into Google’s SERPs first page.</p><p>How can you check whether your keyword is ideal for competition or not?</p><p>Take a look.</p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"78cb77c","elType":"widget","settings":{"title":"SEMrush Keyword Difficulty ","header_size":"h4","title_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":23,"sizes":[]},"typography_font_weight":"600"},"elements":[],"widgetType":"heading"},{"id":"bb4c1b2","elType":"widget","settings":{"editor":"<p>First, you can use the SEMrush’s keyword difficulty. It is a great option that shows you how competitive a given KW is to rank for.</p><p>The “keyword difficulty” is easy to determine if you use SEMrush. Simply enter the keyword into the search field.</p><p>Next find the sidebar and click onto the “keyword difficulty.”</p><p>Now look at the “Difficulty %” column.</p><p>The higher the percentage, the harder it is to rank for the keyword on Google search.</p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"e22902d","elType":"widget","settings":{"title":"Keyword Targeting and Keyword Page Optimization","header_size":"h4","title_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":23,"sizes":[]},"typography_font_weight":"600"},"elements":[],"widgetType":"heading"},{"id":"63f3134","elType":"widget","settings":{"editor":"<p>Now that you have all these down. How do you find out if the page that you’re looking at on the 1<sup>st</sup> page is optimized around the keyword that you have?</p><p>I will show.</p><p>But first, you must understand that this is very important and the reason is simple.</p><p>If you find out that the page ranking on the top 10 SERPs are only slightly related to the keyword in question, then you can easily outrank the page with a highly targeted page.</p><p>This is the trick that’ll work for any new ecommerce website that intends to make it big. </p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"04eb38f","elType":"widget","settings":{"title":"Chapter II: Architecture of an Ecommerce Website ","header_size":"h3","title_color":"#3A4347","typography_typography":"custom","typography_font_weight":"600","typography_font_size":{"unit":"px","size":30,"sizes":[]},"_padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true}},"elements":[],"widgetType":"heading"},{"id":"9c19f36","elType":"widget","settings":{"editor":"<p>How are the pages on your website arranged and organized? Are they appealing or appalling? This is what ecommerce site architecture means – and it’s an important SEO consideration for any website.</p><p>Site architecture is however much more important for the ecommerce websites.</p><p>Why?</p><p>Well, ecommerce websites often have high number of pages than an average blog or local ice cream shop will have.</p><p>As such, it is critical that you arrange the site properly so that you can have a highly presentable website.</p><p>This makes it easy for the users and the site engines to find every page that they are looking for.</p><p>How do you get the best arrangement for your ecommerce website?</p><p>Follow the “Two Golden Rules” of Ecommerce Website Architecture There are two golden rules that determine how you ecommerce website will appear when setting it up.</p><p>These rules are:</p><ul><li>I: Keep the Things Simple and Scalable</li><li>II: Keep Every Page Three or Less Clicks from Your Homepage</li></ul><p>Now that we have the two golden rules, let’s look at:</p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"3cc64d2","elType":"widget","settings":{"title":"How Can the Wrong Site Architecture Hurt You?","header_size":"h5","title_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"600","typography_font_style":"italic","typography_text_decoration":"underline"},"elements":[],"widgetType":"heading"},{"id":"d1eb6f1","elType":"widget","settings":{"editor":"<p>A wrong architecture is not simple. This makes it hard to understand. As such, you won’t understand what should be where and where should what go.</p><p>Because it is not simple, it isn’t scalable. This means that every category that’s added must come with a new layer. So, therefore, some pages will be over three clicks away from the home page, which is bad for business.</p><p>This dilutes authority, becomes extremely boring, and will chase the visitor off the website before they even click on the first product.</p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"b78b1b0","elType":"widget","settings":{"title":"How Can a Good Site Architecture Help Your Ecommerce Site?","header_size":"h5","title_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"600","typography_font_style":"italic","typography_text_decoration":"underline"},"elements":[],"widgetType":"heading"},{"id":"f353715","elType":"widget","settings":{"editor":"<p>The link authority of this type of site is often concentrated around the site’s product and category pages.</p><p>These type of concentrated authority will help the site to rank better in Google. It also makes it easy for Search Engines to find every page in your website and index it.</p><p>A simple architecture also makes it easy for your web page visitors to easily find the products that they are looking for and as such will leave them with a great experience.</p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"b89722c","elType":"widget","settings":{"text":"<u>BONUS</u>: Download 3 Case Studies that Increased Website Profit 132x! ","align":"center","size":"md","icon_indent":{"unit":"px","size":17,"sizes":[]},"wunderwp_presets":null,"typography_typography":"custom","typography_font_family":"Montserrat","typography_font_size":{"unit":"px","size":23,"sizes":[]},"typography_font_weight":"600","text_shadow_text_shadow_type":"yes","button_text_color":"#ffffff","background_color":"#3A4347","hover_color":"#ffffff","border_width":{"unit":"px","top":"2","right":"2","bottom":"2","left":"2","isLinked":true},"border_color":"#FD7C6F","border_radius":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true},"text_padding":{"unit":"px","top":"15","right":"20","bottom":"15","left":"20","isLinked":false}},"elements":[],"widgetType":"button"},{"id":"dd5ac47","elType":"widget","settings":{"space":{"unit":"px","size":30,"sizes":[]}},"elements":[],"widgetType":"spacer"},{"id":"db7db78","elType":"widget","settings":{"title":"Chapter III: On-Page SEO Strategy for Ecommerce ","header_size":"h3","title_color":"#3A4347","typography_typography":"custom","typography_font_weight":"600","typography_font_size":{"unit":"px","size":30,"sizes":[]},"_padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true}},"elements":[],"widgetType":"heading"},{"id":"240d639","elType":"widget","settings":{"editor":"<p>With your ecommerce website architecture already set up. The next thing that you’ll need to do is to optimize your website categories and product pages.</p><p>Proper optimization of these two pages will easily generate the largest share of the website traffic and sales.</p><p>And it makes so much sense if you think of it like this. Someone who’s searching for “medium sized black coat for office” is closer to buying than someone who is searching for “black coat” online.</p><p>So how do you keyword-optimize your product and category pages?</p><p><strong>EXAMPLE OF A PERFECTLY OPTIMIZED ECOMMERCE PAGE</strong></p><p>To get a perfectly optimized keyword-based product and category pages, here is what you have to do.</p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"79ea7c8","elType":"widget","settings":{"title":"I: Modify Your Title Tags","header_size":"h4","title_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":23,"sizes":[]},"typography_font_weight":"600"},"elements":[],"widgetType":"heading"},{"id":"f841c62","elType":"widget","settings":{"editor":"<p>Of course you want to use your keyword on the title tag of your page. This is a great trick. However, it isn’t enough.</p><p>Add modifiers to the title tags. This way, you will show for the long tail keywords too.</p><p>Here are examples of the best modifiers that you can go with.</p><ul><li>Buy</li><li>Deals</li><li>Cheap</li><li>Best</li><li>Online</li><li>Reviews</li><li>Free Shipping</li></ul><p>So instead of having a shorter title tag such as “boxers for men” you will have the “best cheap boxers for men” instead.</p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"03d4705","elType":"widget","settings":{"title":"II: Use Click-Magnet Words on Title Tags ","header_size":"h4","title_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":23,"sizes":[]},"typography_font_weight":"600"},"elements":[],"widgetType":"heading"},{"id":"6f02a8f","elType":"widget","settings":{"editor":"<p>Apart from modifying your title tags with long tail keywords, you can also incorporate click-magnet words.</p><p>The good thing about this is that even Google also recognizes click-through-rate as a ranking factor.</p><p>So if you get the best CTRs you will easily rank higher. Higher CTR also means more conversion rate or sales.</p><p>To boost your click-through-rates, here are some words that you can use.</p><ul><li>Guarantee</li><li>__% off</li><li>Free shipping</li><li>Lowest price</li><li>Overnight sale</li></ul><p>A good example of how these words can be used to boost your click-through-rates include:</p><p>Female Boots: 30% Off with Free Shipping for Every Purchase When used on your title tags or meta descriptions, such phrases will guarantee more clicks.</p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"9eac051","elType":"widget","settings":{"title":"III: Modify Description Tags","header_size":"h4","title_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":23,"sizes":[]},"typography_font_weight":"600"},"elements":[],"widgetType":"heading"},{"id":"2ba6f8e","elType":"widget","settings":{"editor":"<p>The description of your website is very important for your click through rate.</p><p>Thankfully, the same title tag click magnet words that I used above also apply for the description tag.</p><p>The only advantage that the description tag offers is that you’ll get better room to bring in longer phrases.</p><p>If you are looking for some phrases that you can use to modify your description tags, here are some.</p><ul><li>Get the best prices on ­­­­­­­­­­­­­­­­­__________ today.</li><li>All our ­­­­­­­­­­­­­____________ are on sale right now.</li><li>Click here to see all the exclusive deals on ___________</li><li>Get FREE shipping on _____________ today</li><li>Save _________% off on __________</li></ul><p>A good meta description that’s optimized for better clicks might look like this.</p><p>Get the best prices on male shoes today. We offer 30% off on every pair that you purchase. Click here to buy and get Free shipping. </p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"248f8ea","elType":"widget","settings":{"title":"Product and Category Page Content","header_size":"h4","title_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":23,"sizes":[]},"typography_font_weight":"600"},"elements":[],"widgetType":"heading"},{"id":"a8a885b","elType":"widget","settings":{"editor":"<p>Next you want to create a great product and category page content. This is often one of the hardest parts for most people.</p><p>Luckily for you, I have a few strategies that can be of help. If you want to make a high-quality content here are the best SEO tips that you can work with for your ecommerce website.</p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"0909451","elType":"widget","settings":{"title":"Make 1000+ Word Descriptions ","header_size":"h5","title_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"600","typography_font_style":"italic","typography_text_decoration":"underline"},"elements":[],"widgetType":"heading"},{"id":"96edb98","elType":"widget","settings":{"editor":"<p>Latest studies have found out that longer product descriptions or longer content will rank the best on Google SERPs.</p><p>The same findings apply almost everywhere when creating rank-able content.</p><p>How so?</p><p>Google wants to properly understand what the page you are presenting is all about before they can rank it. As such, the more content you create, the mode detailed you become, and the easier to understand you become too.</p><p>In addition to that, creating in-depth content will also help your customers to they are about to buy. This means that you’ll get better user experience benefit too.</p><p>In case you find out that creating 1000+ words for your product description is hard, I highly recommend writing, longer, in-depth product descriptions.</p><p>Do this while focusing on the top 10 to 50 most important product pages and categories on your website.</p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"a4f9e9d","elType":"widget","settings":{"title":"Use Your Keywords Sparingly (3-5X)","header_size":"h5","title_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"600","typography_font_style":"italic","typography_text_decoration":"underline"},"elements":[],"widgetType":"heading"},{"id":"4690902","elType":"widget","settings":{"editor":"<p>Now that you’ve created an in-depth product description, the next thing that you need to ensure is that you have used your keywords in the right way.</p><p>Using the keywords sparingly is often advised since it will look natural. The content won’t be easily misleading.</p><p>The best way to use the keyword is usually 3 to 5 times in your content. Remember, this has nothing to do with keyword stuffing or density.</p><p>Rather, you are only making your content to sound natural and helping Google to easily identify what you are talking about.</p><p>It is important that you have the keyword at least 3 times to create the impression that you are into that topic.</p><p>Here is an example:</p><p>Put one of the keywords in the first 100 words of your product description.</p><p>Put another keyword in the middle of the content.</p><p>Finish the content by again including the keyword in the conclusion of the content.</p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"b50aef5","elType":"widget","settings":{"title":"LSI Keywords ","header_size":"h4","title_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":23,"sizes":[]},"typography_font_weight":"600"},"elements":[],"widgetType":"heading"},{"id":"3b66b65","elType":"widget","settings":{"editor":"<p>LSI keywords in other words <strong><u>Latent Semantic Indexing Keywords</u></strong> help to explain your main keyword. They will closely resemble the main keyword.</p><p>Here is a good example:</p><p>If you are working with “best miter saw” the LSI keywords might include the following:</p><ul><li>Miter saw</li><li>Miter saw stand</li><li>Chop saws</li><li>Saws</li><li>Saw</li><li>Rolling miter saw</li></ul><p>Understand how to include the LSI keywords to meet the needs of your ecommerce business. Here are great tips on how to find the best LSI keywords for ecommerce SEO.</p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"569ec22","elType":"widget","settings":{"title":"Amazon Eyeball Test ","header_size":"h5","title_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"600","typography_font_style":"italic","typography_text_decoration":"underline"},"elements":[],"widgetType":"heading"},{"id":"e267108","elType":"widget","settings":{"editor":"<p>This is simple to work with. All you need to do is to open up Amazon and search for your main keyword.</p><p>You should then look for words that appear several times on the category page of the products that you are looking at.</p><p>These will make the LSI keywords.</p><p>You can do the same for the product page too.</p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"136ed7f","elType":"widget","settings":{"title":"Google Keyword Planner ","header_size":"h5","title_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"600","typography_text_decoration":"underline","typography_font_style":"italic"},"elements":[],"widgetType":"heading"},{"id":"7bae5e9","elType":"widget","settings":{"editor":"<p>GKP is also another great tool that you can use to get the best LSI keywords. Simply enter your target keyword in GKP and look at the suggested keywords.</p><p>Once you have the most suitable LSI keywords, for your product category, the next thing is to sprinkle them in your content. They provide better support to your main keyword.</p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"41cc38d","elType":"widget","settings":{"title":"Short But Keyword-Rich Urls","header_size":"h4","title_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":23,"sizes":[]},"typography_font_weight":"600"},"elements":[],"widgetType":"heading"},{"id":"fa07dab","elType":"widget","settings":{"editor":"<p>I have mentioned it before in some of my contents here. Urls have direct co-relation to the ranking that a web page gets.</p><p>More specifically, the shorter urls tend to rank on the first page much better than the longer urls. However, since you are working with an ecommerce website, you will probably have longer urls most sites.</p><p>Why?</p><p>Your urls will contain categories and also sub categories.</p><p>Nonetheless, that’s no excuse for your urls to overstretch past 50 characters. Longer urls will confuse Google and possibly dilute the intended keyword impact.</p><p>Such as shown here.</p><p>So what can you do?</p><p>Make the url shorter and make it a keyword-rich url.</p><p>Here is an explanation that makes easy and quite sensible.</p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"14c16b8","elType":"widget","settings":{"image":{"url":"https://onlinemarketinghelp.co.uk/wp-content/uploads/2020/09/url-key.png","id":2692},"image_size":"full"},"elements":[],"widgetType":"image"},{"id":"92ea684","elType":"widget","settings":{"space":{"unit":"px","size":30,"sizes":[]}},"elements":[],"widgetType":"spacer"},{"id":"1408c3e","elType":"widget","settings":{"title":"Link to High-Priority Pages for Internal Links","header_size":"h4","title_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":23,"sizes":[]},"typography_font_weight":"600","wunderwp_presets":null},"elements":[],"widgetType":"heading"},{"id":"8f1e721","elType":"widget","settings":{"editor":"<p>Another thing that you’ll love about creating a great ecommerce SEO website is <strong><u>internal link building</u></strong>. It is the easiest to do as it blends in well with great site navigation.</p><p>As such, a strategic link building process is very important. You should, therefore, spend quite some time on it.</p><p>The best way to do that is to link from the high-authority pages to high authority pages (product and category pages).</p><p>Here is an Example:</p><p>If you created a high ranking blog post for a specific keyword (X).</p><p>Then you have a product or category page that ranks lower for the same keyword (X).</p><p>You can add a keyword-rich anchor text right from the high-ranking blog post to the product page.</p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"0176cf5","elType":"widget","settings":{"title":"Chapter IV: Ecommerce: Technical SEO Strategy ","header_size":"h3","title_color":"#3A4347","typography_typography":"custom","typography_font_weight":"600","typography_font_size":{"unit":"px","size":30,"sizes":[]},"_padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true}},"elements":[],"widgetType":"heading"},{"id":"22d1653","elType":"widget","settings":{"editor":"<p>When you come to ecommerce, you’ll find that nothing is more important that technical SEO. The reason is simple. Ecommerce websites often have lots of pages.</p><p>However, most of these pages don’t usually have many backlinks to them.</p><p>As such, technical SEO if often the savior. For better understanding of how technical SEO works for ecommerce websites, you shouldn’t pass in this chapter.</p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"4978f24","elType":"widget","settings":{"title":"Running a Technical SEO Audit on an Ecommerce Website","header_size":"h4","title_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":23,"sizes":[]},"typography_font_weight":"600"},"elements":[],"widgetType":"heading"},{"id":"9bab841","elType":"widget","settings":{"editor":"<p>To run the best technical SEO audit on an ecommerce website, you’ll require a tool that’s built for that.</p><p>One of the easiest tools to use and which I completely recommend is the <a href="https://raventools.com/">Raven Tools</a>. In addition to this tool, here are other <strong><u>SEO tools</u></strong> that you can always go with.</p><ul><li><a href="https://www.deepcrawl.com/">DeepCrawl</a></li><li><a href="https://www.screamingfrog.co.uk/seo-spider/">ScreamingFrog</a></li><li><a href="https://ahrefs.com/">Ahrefs</a></li><li><a href="https://www.semrush.com/">SEMrush</a></li></ul><p>How to use Raven Tools for your technical SEO site audit.</p><ul><li>First open the “left-hand sidebar”</li><li>Choose “Site Auditor”</li><li>Raven analyzes your website for errors</li><li>Raven provides a report</li><li>Scan the report for highlighted issues:</li><li>Duplicate content</li><li>Thin content</li><li>Title problems</li><li>Broken links</li></ul><p>You will have all the possible SEO errors that your website might have. Now how do you solve them?</p><p>Take a look.</p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"aeb437f","elType":"widget","settings":{"title":"Solving Technical SEO Problems on Ecommerce Websites ","header_size":"h4","title_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":23,"sizes":[]},"typography_font_weight":"600"},"elements":[],"widgetType":"heading"},{"id":"2a5361d","elType":"widget","settings":{"editor":"<p>I will highlight the problem that the technical SEO audit revealed and show you how to fix it in this section. Let’s dig in.</p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"78ecb6d","elType":"widget","settings":{"title":"Too Many Pages ","header_size":"h5","title_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"600","typography_text_decoration":"underline","typography_font_style":"italic"},"elements":[],"widgetType":"heading"},{"id":"10fd9b6","elType":"widget","settings":{"editor":"<p>Thousands of pages can be a technical SEO problem. It gives you no chance of creating unique content. Rather, you’ll struggle with <strong><u>duplicate content</u></strong>.</p><p>How does it happen?</p><p>Most ecommerce websites have lots of products to sell (1000+). They need many pages. In addition to that, one product can have slight variations (colors), but still require unique urls. This can also cause it.</p><p>How do you solve it?</p><ul><li>Identify pages that you can do away with (delete or <a href="https://support.google.com/webmasters/answer/93710?hl=en">non-index</a>).</li><li>Make sure the pages cannot affect the idea that you are selling across.</li><li>You can also combine the pages that don’t bring in sales on a single page.</li><li>However, don’t delete them before you confirm that they aren’t generating any traffic.</li><li>Use the <a href="https://analytics.google.com/analytics/web/">Google Analytics</a> tool to do that.</li></ul><p>If the page brings in some money, you can find the best place to combine it. </p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"e80d6f5","elType":"widget","settings":{"title":"Duplicate Content ","header_size":"h5","title_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"600","typography_text_decoration":"underline","typography_font_style":"italic"},"elements":[],"widgetType":"heading"},{"id":"476acdc","elType":"widget","settings":{"editor":"<p>This is dangerous. It can kill your website’s ranking in a whim. The one thing <a href="https://en.wikipedia.org/wiki/Google_Panda">Google Panda</a> determines.</p><p>Luckily, if you use <strong><u>advanced SEO techniques</u></strong> you can eliminate any duplicate content. Another tip that you can practice is the use of <a href="https://moz.com/learn/seo/canonicalization">canonical tags</a>.</p><p>How does it happen?</p><p>There are several reasons to this.</p><ul><li>If you have slight variations on the same product (size and color).</li><li>Your site can create unique urls every product version or page.</li><li>It can also create a unique url for every selection that a visitor makes.</li><li>If search engines index these created urls the result is several duplicate contents.</li></ul><p>In addition to that:</p><p>The use of longer boilerplate content (100+ words) can create an impression of content duplication.</p><p>So if you have to use the same boilerplate content for every page, keep it short and way below 100 words.</p><p>Finally, the use of copied content or product descriptions can also be set as duplicate. This happens when you are dealing with a similar product but with slight variation.</p><p>This happens often on category or product pages. It is not good and will be easily categorized by search engines as duplicate content.</p><p>How do you solve it?</p><ul><li>Non-index the pages that don’t put money in your pocket or bring in traffic.</li><li>Next tap into the canonical tags (shows that some pages are copies or slight variations of the same page).</li><li>Create unique content for every page that you don’t non-index (it is tough but without any shortcut if you intend to rank and make money).</li></ul><p>NOTE: Canonicalization solves duplicate content. More importantly, makes your backlinks extremely valuable (links that point to many other different urls will route to just one url).</p><p>An easy way to create unique content is to have template for your category and product page descriptions.</p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"2b9a171","elType":"widget","settings":{"title":"Thin Content ","header_size":"h5","title_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"600","typography_text_decoration":"underline","typography_font_style":"italic"},"elements":[],"widgetType":"heading"},{"id":"42abb74","elType":"widget","settings":{"editor":"<p>Shallow or thin content is another huge problem for SEO sites. It is not tied to duplicate content at all and can come with or without duplication of content.</p><p>This content is bad and can actually <a href="http://searchengineland.com/panda-4-0s-big-loser-ebay-winners-losers-chart-192123">mess up your ecommerce SEO campaign up to a greater margin</a>. So work with rich and longer content.</p><p>How does it happen?</p><p>So how does ecommerce websites end up with thin content? It is hard to create longer and unique content for similar products. But that’s no excuse really.</p><p>For all your important pages (product and category), you should be able to squeeze in 500+ words of unique content.</p><p>How do you solve it?</p><ul><li>Identify pages with thin content.</li><li>These are short snippets that don’t add any value to your campaign.</li><li>Use the Raven Tool (above) or go through every page.</li><li>Bulk up the pages that you find with high-quality content</li><li>The templates will help in easing up the process</li></ul>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"462d759","elType":"widget","settings":{"title":"Site Speed","header_size":"h5","title_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"600","typography_text_decoration":"underline","typography_font_style":"italic"},"elements":[],"widgetType":"heading"},{"id":"37029f8","elType":"widget","settings":{"editor":"<p>I mentioned in one of my previous contents that site speed is something that Google pays attention to and turns to for ranking.</p><p>It is important for ecommerce SEO and also <a href="http://blog.radware.com/applicationdelivery/applicationaccelerationoptimization/2013/05/case-study-page-load-time-conversions/">influences the buying patterns of your website visitors</a>.</p><p>How does it happen?</p><ul><li>Some ecommerce sites are slow because of bloated codes.</li><li>Large image sizes also slow down sites.</li><li>Slow hosting servers.</li></ul><p>How do you solve it?</p><ul><li>Install a plugin to boost speed</li><li>Trim down (Compress) the size of images using better codes</li><li>Change your hosting server</li></ul>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"98d1714","elType":"widget","settings":{"title":"Chapter V: Ecommerce Content Marketing Strategy","header_size":"h3","title_color":"#3A4347","typography_typography":"custom","typography_font_weight":"600","typography_font_size":{"unit":"px","size":30,"sizes":[]},"_padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true}},"elements":[],"widgetType":"heading"},{"id":"b9f1717","elType":"widget","settings":{"editor":"<p>Another thing that I wouldn’t wish to leave out is the need for proper content marketing strategy. While most people might brush it off – I won’t.</p><p>Proper content marketing strategy can get you lots of targeted traffic in a SEO campaign.</p><p>But how do you use it to get better ranking or more traffic for your ecommerce website? Take a look at the following smart guide.</p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"9bf7777","elType":"widget","settings":{"title":"Step I: Find Your Target Audience and Where They Converge Online","header_size":"h4","title_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":23,"sizes":[]},"typography_font_weight":"600"},"elements":[],"widgetType":"heading"},{"id":"95ea2b4","elType":"widget","settings":{"editor":"<p>Look for discussion groups, online communities, and other areas where your prospects hang out.</p><p>This platforms offer the best places for tapping into your customer’s thoughts, desires, and dreams. You can easily tap into their true feelings.</p><p>A good platform to start from is the <a href="http://www.reddit.com/">Reddit</a>.</p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"4858ab6","elType":"widget","settings":{"title":"Step II: Learn Customer Terminologies ","header_size":"h4","title_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":23,"sizes":[]},"typography_font_weight":"600"},"elements":[],"widgetType":"heading"},{"id":"82c1671","elType":"widget","settings":{"editor":"<p>What words or phrases do your customers use? Using the same words allows you to draw to their emotions.</p><p>Learn how they articulate their concerns and the words they use to describe them. These words will for your audiences keywords – what they search for over the internet most.</p><p>The words also form an awesome basis for your blog content. </p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"9c7fc08","elType":"widget","settings":{"title":"Step III: Use the Keywords for Awesome Content","header_size":"h4","title_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":23,"sizes":[]},"typography_font_weight":"600"},"elements":[],"widgetType":"heading"},{"id":"c384214","elType":"widget","settings":{"editor":"<p>Now that you have your keywords ready, don’t waste any time. Create a unique piece of content around the keyword.</p><p>Once you have this unique piece of content, post it on your website and follow this ultimate guide once again.</p><p>With the links, social media shares, traffic, and other SEO tips for ecommerce, you should rank better on SERPs.</p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"6ec0833","elType":"widget","settings":{"title":"Chapter VI: Link Building for Ecommerce ","header_size":"h3","title_color":"#3A4347","typography_typography":"custom","typography_font_weight":"600","typography_font_size":{"unit":"px","size":30,"sizes":[]},"_padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true}},"elements":[],"widgetType":"heading"},{"id":"efaccd8","elType":"widget","settings":{"editor":"<p>Finally, for this ultimate guide to ecommerce SEO, I am going to include the best link building strategies for ecommerce.</p><p>I will show you how you can build links directly to your ecommerce websites without using any content.</p><p>Then I will also show you how you can use two major link building strategies to boost your site’s organic traffic.</p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"ded7f13","elType":"widget","settings":{"title":"Moving Man Method","header_size":"h4","title_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":23,"sizes":[]},"typography_font_weight":"600"},"elements":[],"widgetType":"heading"},{"id":"d53e83d","elType":"widget","settings":{"editor":"<p>This method is super cool. You can use to tap into the best link building from highly relevant websites. This method provides you with contextual links that you can easily rely on.</p><p>How It Works</p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"6df081b","elType":"widget","settings":{"title":"Step I: ","header_size":"h5","title_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"600","typography_text_decoration":"underline","typography_font_style":"italic"},"elements":[],"widgetType":"heading"},{"id":"4c6acee","elType":"widget","settings":{"editor":"<p>Hunt for expired, moved, or outdated resources (zero in on companies that have closed shop).</p><ul><li>Their domain names expire.</li><li>Their sites are replaced with parked pages.</li></ul><p>They are ideal since they give you non-competitive link building opportunities that your competitors aren’t aware of.</p><p>To get these links, use big domain auction sites such as the <a href="https://auctions.godaddy.com/">GoDaddy Auctions</a> and <a href="http://www.namejet.com/">NameJet</a> since they collect such in one place.</p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"6147e58","elType":"widget","settings":{"title":"Step II:","header_size":"h5","title_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"600","typography_text_decoration":"underline","typography_font_style":"italic"},"elements":[],"widgetType":"heading"},{"id":"b6231a8","elType":"widget","settings":{"editor":"<p>Identify a parked domain that falls in the same niche as you. This is where your hard work comes in handy.</p><p>Note: These companies are out of businesses. As such they are not (404 links). Their links are still in operation.</p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"26aef13","elType":"widget","settings":{"title":"Step III:","header_size":"h5","title_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"600","typography_text_decoration":"underline","typography_font_style":"italic"},"elements":[],"widgetType":"heading"},{"id":"30449b2","elType":"widget","settings":{"editor":"<p>The next thing is to find the sites that these outdated links or resource links to. This is very important.</p><p>Here is how you do that.</p><ul><li>First, get the url of the outdated source.</li><li>Enter the url on the Ahrefs domain.</li><li>Find the “edge design”</li><li>Find the number of “referring domains”</li><li>Click on “backlinks” to see all pages that link to this outdated source</li></ul><p>Note: The more the referring domains the more the linking opportunities.</p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"d382f94","elType":"widget","settings":{"title":"Step IV:","header_size":"h5","title_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"600","typography_text_decoration":"underline","typography_font_style":"italic"},"elements":[],"widgetType":"heading"},{"id":"5677737","elType":"widget","settings":{"editor":"<p>Finally, you’ll send emails and ask for opportunities to link for the same outdated sources. Let them know the links are outdated and referring to dead sources. Then ask them offer them the replacement link.</p><p>Do not ask for favors. Instead, ensure that you have prepared high-quality content that offers value to the same website that you are asking to link to.</p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"c0c447d","elType":"widget","settings":{"title":"Social Media Group Events ","header_size":"h4","title_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":23,"sizes":[]},"typography_font_weight":"600"},"elements":[],"widgetType":"heading"},{"id":"b993083","elType":"widget","settings":{"editor":"<p>Another trick that you can use is the social media group events. This is easier to follow but with great results.</p><ul><li>First identify groups from your niche that have put on events</li><li>Next identify the events which require stuff</li><li>Find out if the stuff you offer are required</li><li>Now reach out to the organizers of the event – ask if they’d love to feature your products.</li><li>If can’t ask you can send them free gift products and hope that they are featured.</li><li>Send your products and offer to ship back what’s not used on your cost.</li><li>Stay in the loop and follow the posts that they write over the event.</li><li>Ask them if they can credit you with a link when the post goes live.</li><li>Thank them when they do.</li></ul><p>The whole process might look tedious. However, it is no different from the above. If you stick to it you can easily get the best out of it.</p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"422832c","elType":"widget","settings":{"title":"Let Me Know What You Think:","header_size":"h4","title_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":23,"sizes":[]},"typography_font_weight":"600"},"elements":[],"widgetType":"heading"},{"id":"2d1e99b","elType":"widget","settings":{"editor":"<p>Do you want to get down to a new ecommerce SEO campaign?</p><p>Is there a new strategy that you want to practice?</p><p>Do you have anything in mind that I didn’t include here?</p><p>Feel free to share. Let us work together to give the best for all SEO lovers out there.</p><p>You can leave a comment on the commentary section and I will reply to it right away!</p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"fd5bc8f","elType":"widget","settings":{"title":"Meta ","header_size":"h4","title_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":23,"sizes":[]},"typography_font_weight":"600"},"elements":[],"widgetType":"heading"},{"id":"97bc05d","elType":"widget","settings":{"editor":"<p>Are you in need of the best ecommerce SEO strategy? Get the best SEO strategy for Ecommerce. We have the ultimate guide for ecommerce SEO.</p>","text_color":"#3A4347","typography_typography":"custom","typography_font_size":{"unit":"px","size":20,"sizes":[]},"typography_font_weight":"400"},"elements":[],"widgetType":"text-editor"},{"id":"8374a89","elType":"section","settings":{"height_inner":"min-height","custom_height_inner":{"unit":"px","size":"","sizes":[]},"background_overlay_position":"center center","background_overlay_repeat":"no-repeat","background_overlay_size":"cover","background_overlay_opacity":{"unit":"px","size":"1","sizes":[]},"border_radius":{"unit":"px","top":"15","right":"15","bottom":"15","left":"15","isLinked":"1"},"box_shadow_box_shadow":{"horizontal":"0","vertical":"0","blur":"25","spread":"0","color":"rgba(0,0,0,0.1)"},"margin":{"unit":"px","top":"80","right":"0","bottom":"80","left":"0","isLinked":"1"},"background_overlay_position_mobile":"initial","background_overlay_xpos_mobile":{"unit":"px","size":"-543","sizes":[]},"background_overlay_image":{"id":2315,"url":"https://onlinemarketinghelp.co.uk/wp-content/uploads/2020/09/BG-Post-Sub.png"},"_title":"Subscribe Inner Section","premium_parallax_layers_list":[],"premium_gradient_colors_repeater":[],"premium_kenburns_repeater":[],"premium_lottie_repeater":[],"premium_blob_repeater":[],"pa_condition_repeater":[{"_id":"8ff6d5d","pa_condition_key":"browser","pa_condition_valshortcode":"","pa_condition_valtime_range":"","pa_condition_operator":"is","pa_condition_url_string":"","pa_condition_url_referer":"